import{_ as a,o as s,c as n,a2 as o}from"./chunks/framework.BWuWLRhz.js";const m=JSON.parse('{"title":"Índice","description":"","frontmatter":{},"headers":[],"relativePath":"es-ES/user-guide/settings/index-drives.md","filePath":"es-ES/user-guide/settings/index-drives.md","lastUpdated":1787130161000}'),r={name:"es-ES/user-guide/settings/index-drives.md"};function i(d,e,t,l,c,u){return s(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="indice" tabindex="-1">Índice <a class="header-anchor" href="#indice" aria-label="Permalink to &quot;Índice&quot;">​</a></h1><p>Cinco pestañas, en orden: <strong>Unidades locales</strong>, <strong>Unidades de red</strong>, <strong>WSL</strong> (solo se muestra al detectar una distribución), <strong>Carpetas</strong>, y <strong>Reglas de exclusión</strong>.</p><h2 id="unidades-locales" tabindex="-1">Unidades locales <a class="header-anchor" href="#unidades-locales" aria-label="Permalink to &quot;Unidades locales&quot;">​</a></h2><ul><li>Tarjeta de estado que resume cuántas unidades y elementos están indexados, más un botón <strong>Reconstruir índice</strong> para un reescaneo completo.</li><li>Una fila por unidad local: una <strong>casilla de habilitar/deshabilitar</strong>, nombre de la unidad, sistema de archivos (NTFS/ReFS/...), estado actual, número de elementos indexados, y una acción por fila de <strong>Reconstruir</strong>/<strong>Eliminar</strong> — más una acción <strong>Detener</strong> mientras hay una reconstrucción en curso, para toda unidad excepto las NTFS reales (su escaneo no tiene un punto seguro donde interrumpirse).</li><li>Las unidades NTFS y ReFS registran los cambios de forma continua a través del USN Journal de Windows; otros sistemas de archivos locales (FAT32, exFAT, ...) no tienen ningún journal que leer, así que se vigilan directamente en busca de cambios en su lugar. En cualquier caso, rara vez hace falta una reconstrucción manual, pero está ahí por si algo parece desincronizado — y si una se interrumpe (se detiene, o la app/servicio se reinicia a mitad de escaneo), la siguiente reconstrucción continúa desde donde se quedó en lugar de empezar de cero.</li></ul><p>La selección de unidades habilitadas se respeta literalmente: si desmarcas todas las casillas, la indexación de unidades locales permanece deshabilitada en vez de volver a seleccionar todas las unidades en silencio. Las configuraciones existentes de versiones donde una selección vacía significaba «todas las unidades» se migran una sola vez para que una actualización no deshabilite inesperadamente la indexación.</p><p>La búsqueda sigue funcionando mientras se reconstruye un índice. La unidad que se está reconstruyendo continúa respondiendo con su índice anterior hasta que el nuevo esté listo, y las demás unidades no se ven afectadas: una reconstrucción nunca te deja con una lista de resultados vacía.</p><h2 id="unidades-de-red" tabindex="-1">Unidades de red <a class="header-anchor" href="#unidades-de-red" aria-label="Permalink to &quot;Unidades de red&quot;">​</a></h2><ul><li>La misma tarjeta de estado y botón <strong>Reconstruir índice</strong> que Unidades locales.</li><li>Una fila por cada unidad de red asignada: casilla de habilitar, ruta/nombre, estado (Indexando / Lista / En caché / Fallida / Pendiente / Conectada), número de elementos, y un desplegable <strong>Modo de actualización</strong>: <ul><li><strong>Manual</strong> — solo se actualiza bajo demanda (mediante Reconstruir índice).</li><li><strong>Cada 15 minutos</strong></li><li><strong>Cada hora</strong></li><li><strong>Diario</strong></li></ul></li></ul><p>Los recursos de red no exponen un journal de cambios como sí lo hacen los volúmenes NTFS locales, por eso se actualizan según una programación en lugar de en tiempo real. El motor de escaneo incluye un mecanismo integrado de seguimiento de rutas y detección de bucles de enlaces simbólicos, interceptando bucles infinitos en recursos compartidos NAS/SMB para garantizar un recuento preciso.</p><h2 id="wsl" tabindex="-1">WSL <a class="header-anchor" href="#wsl" aria-label="Permalink to &quot;WSL&quot;">​</a></h2><p>Solo se muestra al detectarse al menos una distribución de WSL — la misma estructura que Unidades de red (tarjeta de estado, botón <strong>Reconstruir índice</strong>, y una fila por distribución con estado/número de elementos/<strong>Modo de actualización</strong>). Las distribuciones se detectan automáticamente; no hay ningún paso manual de &quot;añadir&quot;.</p><p>Los resultados de búsqueda de WSL siempre proceden del índice actual. Lertaro no sondea el sistema de archivos de WSL durante la búsqueda, por lo que el resultado refleja el estado indexado hasta la siguiente actualización o reconstrucción. Abrir o previsualizar un resultado sí puede acceder al archivo, ya que es una acción solicitada explícitamente por el usuario.</p><h2 id="carpetas" tabindex="-1">Carpetas <a class="header-anchor" href="#carpetas" aria-label="Permalink to &quot;Carpetas&quot;">​</a></h2><p>Indexa carpetas individuales arbitrarias en lugar de una unidad o recurso compartido entero — útil para indexar solo un subárbol sin arrastrar todo lo demás de ese volumen.</p><ul><li>Un botón <strong>Añadir carpeta</strong> abre un selector de carpetas con selección múltiple; mantén pulsada Ctrl o Shift para añadir varias carpetas de una vez. Las selecciones duplicadas se ignoran. Un botón <strong>Reconstruir índice</strong> vuelve a escanear cada carpeta de la lista.</li><li>Una fila por carpeta añadida: casilla de habilitar, ruta, estado, número de elementos, y el mismo desplegable <strong>Modo de actualización</strong> (Manual / Cada 15 minutos / Cada hora / Diario) que las unidades de red — las carpetas se escanean según una programación en lugar de vigilarse de forma continua, igual que los recursos de red.</li><li>El selector de carpetas también acepta una <strong>ruta de recurso compartido de red UNC</strong> (por ejemplo, <code>\\\\servidor\\recurso</code>, o una subcarpeta dentro de ella) navegando a través de <em>Red</em> en el selector — útil para indexar un único recurso compartido o subárbol sin añadir el servidor entero como una unidad de red asignada.</li></ul><h2 id="reglas-de-exclusion" tabindex="-1">Reglas de exclusión <a class="header-anchor" href="#reglas-de-exclusion" aria-label="Permalink to &quot;Reglas de exclusión&quot;">​</a></h2><p>Tres subpestañas, cada una con la misma estructura: un cuadro de texto de una sola entrada + botón <strong>Añadir</strong>, una lista de reglas existentes (cada una editable/eliminable), y un cuadro de texto masivo de varias líneas con botones <strong>Generar desde la lista</strong> / <strong>Aplicar a la lista</strong> para editar todo a la vez.</p><ul><li><strong>Exclusiones de ruta</strong> — rutas completas o variables de entorno (por ejemplo, <code>D:\\Cache</code>, <code>%ProgramData%</code>).</li><li><strong>Comodines glob</strong> — <code>*</code> (cualquier carácter en un nombre de archivo), <code>?</code> (un solo carácter), <code>**</code> (directorios recursivos). Ejemplos: <code>*.tmp</code>, <code>**/node_modules/**</code>, <code>bin/**</code>.</li><li><strong>Patrones regex</strong> — expresiones regulares arbitrarias comparadas contra la ruta/nombre de archivo (coincidencia parcial). Ejemplos: <code>^\\.</code> (archivos ocultos), <code>~$</code> (archivos temporales de Office), <code>\\.git\\</code>.</li></ul><p>Las exclusiones se aplican por igual a la indexación local, de red y de carpetas, y las unidades/carpetas de red se vuelven a escanear automáticamente después de aplicar cambios en las reglas de exclusión.</p>',19)])])}const g=a(r,[["render",i]]);export{m as __pageData,g as default};
